// ==========================================================
// COLIGO — module partagé
// Statuts, couleurs, logo, et reçu thermique en double exemplaire.
// Chargé par index.html, agent.html et Admin.html.
// ==========================================================

// Les 4 statuts du système.
const STATUTS = ['Enregistré', 'En transit', 'Disponible', 'Retiré'];

// La couleur d'un statut dit ce qu'il faut en faire, et rien d'autre :
//   Enregistré → ardoise : le colis attend, personne n'a rien à faire.
//   En transit → cyan    : il bouge, on le suit.
//   Disponible → ambre   : action requise, le client doit venir le retirer.
//   Retiré     → vert    : dossier clos.
// Le bleu de la marque n'apparaît jamais ici : il est réservé à
// l'interface (boutons, liens), pour ne pas créer de confusion.
const STATUT_COLORS = {
  'Enregistré': { bg: '#EDF1F6', text: '#48596E', solid: '#5B6B7F' },
  'En transit': { bg: '#E2F1F8', text: '#0E6F94', solid: '#1189B5' },
  'Disponible': { bg: '#FDF2E2', text: '#9A590B', solid: '#C97C10' },
  'Retiré':     { bg: '#E5F4EF', text: '#106349', solid: '#15795A' }
};

// Statuts que l'on peut choisir à la main dans "Mettre à jour le statut".
// "Retiré" n'y figure pas volontairement : il ne peut être posé que depuis
// l'espace Retraits, qui exige les informations de la personne qui retire.
const STATUTS_MODIFIABLES = STATUTS.filter(s => s !== 'Retiré');

// Les anciens colis en base peuvent encore porter les anciens statuts (avant
// le passage à ce système). On les ramène vers les statuts actuels.
const ANCIENS_STATUTS = {
  'Pris en charge': 'En transit',
  'Arrivé à destination': 'En transit',
  'Disponible pour retrait': 'Disponible',
  'Livré': 'Retiré'
};

function normalizeStatut(s) {
  if (!s) return 'Enregistré';
  if (STATUTS.includes(s)) return s;
  return ANCIENS_STATUTS[s] || 'Enregistré';
}

function statutColors(s) {
  return STATUT_COLORS[normalizeStatut(s)] || STATUT_COLORS['Enregistré'];
}

// Comparaison de ville/agence insensible aux accents, à la casse et aux espaces.
function normalizeCity(s) {
  return (s || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

// Code à 3 lettres utilisé au début du numéro de suivi.
// Format retenu : AGENCExxxxxx/AA (ex : DLA000000/26, YDE000000/26).
const AGENCE_CODES = { douala: 'DLA', yaounde: 'YDE' };

// Une seule agence en face de l'autre : le trajet est toujours entre
// Yaoundé et Douala. Utile pour l'auto-remplissage à l'enregistrement
// ET pour cibler "l'agence d'en face" (temps réel, listings reçus…).
function villeArriveePour(agence) {
  return normalizeCity(agence) === 'douala' ? 'Yaoundé' : 'Douala';
}

// Met à jour la présence réelle d'un agent (colonnes en_ligne,
// derniere_connexion, derniere_deconnexion — voir
// sql/presence_agents_migration.sql). Utilisée par agent.js et retrait.js
// à la connexion et à la déconnexion. On ignore silencieusement l'erreur
// si la migration n'a pas encore été exécutée (colonnes absentes) : ça ne
// doit jamais bloquer la connexion/déconnexion elle-même.
async function marquerPresence(agentId, enLigne) {
  try {
    const champ = enLigne ? { en_ligne: true, derniere_connexion: new Date().toISOString() }
                           : { en_ligne: false, derniere_deconnexion: new Date().toISOString() };
    await supabaseClient.from('agents').update(champ).eq('id', agentId);
  } catch (e) { /* silencieux : ne doit jamais empêcher la connexion/déconnexion */ }
}

// Fermeture de l'espace sans passer par « Se déconnecter » (onglet ou fenêtre
// fermé) : la session du navigateur disparaît d'elle-même, mais la présence
// en base restait « en ligne ». On marque donc l'agent hors ligne à la
// fermeture. fetch(..., { keepalive: true }) est nécessaire : une requête
// normale serait annulée par le navigateur pendant la fermeture de la page.
// Si la page est simplement rechargée, la reprise de session (agent.js /
// retrait.js) remet l'agent « en ligne » aussitôt.
function activerDeconnexionALaFermeture() {
  window.addEventListener('pagehide', () => {
    try {
      const raw = sessionStorage.getItem('coligo_agent_session');
      if (!raw) return; // déjà déconnecté via le bouton
      const a = JSON.parse(raw);
      fetch(`${SUPABASE_URL}/rest/v1/agents?id=eq.${encodeURIComponent(a.id)}`, {
        method: 'PATCH',
        keepalive: true,
        headers: {
          apikey: SUPABASE_ANON_KEY,
          Authorization: 'Bearer ' + SUPABASE_ANON_KEY,
          'Content-Type': 'application/json',
          Prefer: 'return=minimal'
        },
        body: JSON.stringify({ en_ligne: false, derniere_deconnexion: new Date().toISOString() })
      });
    } catch (e) { /* silencieux */ }
  });
  // Retour sur la page via le bouton « précédent » (page restaurée depuis le cache) : la session existe encore.
  window.addEventListener('pageshow', (e) => {
    if (!e.persisted) return;
    try {
      const raw = sessionStorage.getItem('coligo_agent_session');
      if (raw) marquerPresence(JSON.parse(raw).id, true);
    } catch (err) { /* silencieux */ }
  });
}
activerDeconnexionALaFermeture();

function agenceCode(agence) {
  const key = normalizeCity(agence);
  if (AGENCE_CODES[key]) return AGENCE_CODES[key];
  // Repli pour une agence non prévue dans la liste ci-dessus : ses 3
  // premières lettres. Pensez à ajouter le vrai code dans AGENCE_CODES
  // si une nouvelle agence ouvre.
  const lettres = (agence || 'AGE').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/[^A-Z]/g, '');
  return (lettres.slice(0, 3) || 'AGE').padEnd(3, 'X');
}

// Logo COLIGO (PNG à fond transparent) encodé en base64 : les fenêtres
// d'impression (reçu, listing) s'ouvrent vides, sans accès aux fichiers du
// site, donc l'image doit être intégrée directement dans le HTML imprimé.
const COLIGO_LOGO_B64 = '';

function fcfa(n) {
  return Number(n || 0).toLocaleString('fr-FR') + ' FCFA';
}

// ----------------------------------------------------------
// Détection des colis à regrouper en listing.
// ----------------------------------------------------------

// Bouteilles de gaz.
function estColisBG(description) {
  const d = (description || '').toString();
  return /\bBG\b/i.test(d) || /bouteille.*gaz/i.test(d);
}

// Colis groupés : "02 colis", "4 colis", … jusqu'à "n colis".
function estColisGroupe(description) {
  const d = (description || '').toString().trim();
  return /^\d+\s*colis\b/i.test(d);
}

// Numéro de listing : N°0001 DLA / N°0001 YDE (séquence propre à chaque agence).
async function genererNumeroListing(agence) {
  const code = agenceCode(agence);
  const { count } = await supabaseClient
    .from('listings')
    .select('*', { count: 'exact', head: true })
    .eq('agence', agence);
  return `N°${String((count || 0) + 1).padStart(4, '0')} ${code}`;
}

// Compare deux numéros de listing en ignorant espaces, casse et le symbole °,
// pour que la saisie fonctionne même mal formatée ("0001dla", "N 0001 DLA"…).
function normaliserNumeroListing(s) {
  return (s || '').toString().toUpperCase().replace(/[^A-Z0-9]/g, '');
}

// ----------------------------------------------------------
// Impression A4 d'un listing (BG ou gros envois), avec logo, immatriculation
// du bus à remplir au stylo, et les deux signatures (expédition / réception).
// ----------------------------------------------------------

